const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Lake Killamperpunna, South Australia
  const lakeLoc = ee.Geometry.Point([139.5, -29.9]);
  const lakeRegion = lakeLoc.buffer(5000); // 5km buffer around lake center

  const date1 = '2025-06-20';
  const date2 = '2025-09-15';

  // 2. Data Acquisition & Check
  // Try Sentinel-2 first for 2025
  let col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lakeRegion)
    .filterDate(date1, ee.Date(date1).advance(3, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  let col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lakeRegion)
    .filterDate(date2, ee.Date(date2).advance(3, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`Images for ${date1}: ${size1}`);
  console.log(`Images for ${date2}: ${size2}`);

  // If 2025 data not available, try 2024
  if (size1 === 0 || size2 === 0) {
    console.log("2025 data unavailable, trying 2024...");
    col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(lakeRegion)
      .filterDate('2024-06-20', '2024-06-23')
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

    col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(lakeRegion)
      .filterDate('2024-09-15', '2024-09-18')
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

    const size1_2024 = await col1.size().getInfo();
    const size2_2024 = await col2.size().getInfo();

    console.log(`Images for 2024-06-20: ${size1_2024}`);
    console.log(`Images for 2024-09-15: ${size2_2024}`);

    if (size1_2024 === 0 || size2_2024 === 0) {
      console.log("No data available for both periods.");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 3. Processing - Cloud masking and NDWI calculation
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudMask = qa.bitwiseAnd(1 << 10).eq(0)
      .and(qa.bitwiseAnd(1 << 11).eq(0));
    return image.updateMask(cloudMask);
  }

  function addNDWI(image) {
    const ndwi = image.normalizedDifference(['B3', 'B8']).rename('NDWI');
    return image.addBands(ndwi);
  }

  const img1 = col1.map(maskClouds).map(addNDWI).median();
  const img2 = col2.map(maskClouds).map(addNDWI).median();

  // Check for valid pixels
  const count1 = await img1.select('NDWI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  const count2 = await img2.select('NDWI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  console.log(`Valid pixels date1: ${count1}`);
  console.log(`Valid pixels date2: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log("No valid pixels after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculate water extent (pixels with NDWI > 0)
  const water1 = img1.select('NDWI').gt(0);
  const water2 = img2.select('NDWI').gt(0);

  const waterArea1 = await water1.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  const waterArea2 = await water2.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  console.log(`Water pixels June: ${waterArea1}`);
  console.log(`Water pixels September: ${waterArea2}`);

  // 5. Validation & Final Answer
  if (waterArea1 === null || waterArea2 === null || 
      isNaN(waterArea1) || isNaN(waterArea2)) {
    console.log("Calculation failed - invalid result.");
    console.log("<answer>C3</answer>");
    return;
  }

  const increase = waterArea2 - waterArea1;
  console.log(`Change in water extent: ${increase.toFixed(2)} pixels`);

  if (increase > 0) {
    console.log("Water extent increased.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Water extent did not increase.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
